/* Define a static configuration struct for custom_load_factor_map.
 * The SYS_HASHMAP_DEFAULT_DEFINE_ADVANCED macro takes the address of
 * this struct. If a compound literal (like SYS_HASHMAP_CONFIG(...))
 * were passed directly, it would result in a dangling pointer because
 * compound literals passed as arguments have automatic storage duration.
 */
static const struct sys_hashmap_config custom_map_config_static =
	SYS_HASHMAP_CONFIG(SIZE_MAX, CUSTOM_LOAD_FACTOR);

SYS_HASHMAP_DEFINE(map);
SYS_HASHMAP_DEFAULT_DEFINE_ADVANCED(custom_load_factor_map, sys_hash32, realloc,
				    custom_map_config_static);

