 * The 'map' hashmap, defined by SYS_HASHMAP_DEFINE, has its internal
 * data struct zero-initialized by the macro itself.
 */
extern struct sys_hashmap_data custom_load_factor_map_data;

static void *setup(void)
{
	printk("CONFIG_TEST_LIB_HASH_MAP_MAX_ENTRIES: %u\n", CONFIG_TEST_LIB_HASH_MAP_MAX_ENTRIES);

