	 * 'custom_load_factor_map_data' as a static __noinit struct,
	 * and 'custom_load_factor_map.data' points to it.
	 * This struct must be explicitly zeroed before the hash map is used.
	 */
	memset(&custom_load_factor_map_data, 0, sizeof(custom_load_factor_map_data));

