	 * macros, with the correct hash_func, realloc_func, and config pointers.
	 * Calling sys_hashmap_init would incorrectly set hmap->data to NULL,
	 * as it's designed for initializing a hashmap struct from scratch,
	 * not one whose 'data' pointer is already set by a macro.
	 */

	return NULL;
}
